import{_ as p,c as e,o as r,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"大有","description":"高島易斷 - 大有","frontmatter":{"title":"大有","description":"高島易斷 - 大有"},"headers":[],"relativePath":"classics/takashima/014.md","filePath":"classics/takashima/014.md"}'),i={name:"classics/takashima/014.md"};function l(n,a,d,t,s,c){return r(),e("div",null,[...a[0]||(a[0]=[h('<h1 id="大有" tabindex="-1">大有 <a class="header-anchor" href="#大有" aria-label="Permalink to “大有”">​</a></h1><h2 id="大有-1" tabindex="-1">大有 <a class="header-anchor" href="#大有-1" aria-label="Permalink to “大有”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>大有：元亨。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《正義》曰：柔處尊位，群陽並應，能大所有，故稱《大有》。元為善之長，大有得《乾》之元，以流行成化，故以“元亨”歸之。程子曰：諸卦“元亨利貞”，《彖》皆釋為“大亨”，恐與《乾》《坤》同也。凡卦有“元亨”者四，《大有》、《蠱》、《升》、《鼎》也。</p><h2 id="象辭" tabindex="-1">象辭 <a class="header-anchor" href="#象辭" aria-label="Permalink to “象辭”">​</a></h2><p>火在天上，大有，君子以遏惡揚善，順天休命。</p><h2 id="象辭注" tabindex="-1">象辭注 <a class="header-anchor" href="#象辭注" aria-label="Permalink to “象辭注”">​</a></h2><p>《離》為日，乾為天，日在天上，照見物之繁多，故曰《大有》。夫“日在天上”明至也，明至則公明正大，而善惡無逃。君子體天，善則舉之，惡則抑之，慶賞威罰，各得其當，即福善禍淫之道也，故曰“遏惡揚善，順天休命”。其“遏惡”，使其有所懲也；其“揚善”使之有所勸也。民能懲惡勸善，天下豈有不治者哉！夫天命之性，有善而無惡，“遏惡揚善”亦不過順天命之本然。推之討有罪，奉天之休命而遏之也；命有德，奉天之休命而揚之也。五刑五用，怒非有私，五服五章，喜非有私，於是惡無不化，善無不勸，大有之治，長保永久也。</p><h2 id="占斷" tabindex="-1">占斷 <a class="header-anchor" href="#占斷" aria-label="Permalink to “占斷”">​</a></h2><p>○　問時運：目下亨通，如日在天上，有光明遍照之象。</p><p>○　問商業：可放膽大做，有富有日新之象。</p><p>○　問家宅：必是祖基素封，積善之家，宜誡勸子弟，培植善根，家業可永保也。</p><p>○　問戰徵：主將星明耀，賞罰得中，萬軍用命之象。</p><p>○　問行人：必滿載而歸，大利。</p><p>○　問六甲：生男。</p><p>○　問疾病：不利。</p><p>○　問訟事：主公明斷結，否則亦必和息。</p><h2 id="初九解" tabindex="-1">初九解 <a class="header-anchor" href="#初九解" aria-label="Permalink to “初九解”">​</a></h2><p>“交害”者，涉害也。九居一卦之初，雖卦屬富有，初陽在下，未與物交，所以未涉於害也，何咎之有？凡處富有之時，易致自滿，滿則驕生，驕生則害即隨之，有害即有咎。惟時時克思厥艱，斯小心敬懼，有而不自以為有，即出而無相交，必矢刻苦自勸之心，不敢稍存驕盈之念，故曰“艱則無咎”。蓋富有本非有咎，在初時未交於害，以為“非咎”，則一交而遂得咎者，咎由自取之耳。能思其艱難，則可以保其有，即可以免其咎。《象傳》曰“《大有》初九”，言當《大有》初爻，無所交涉，不關災害也。一說，訓“無交害”三字，為國無交而害者，蓋以初九之應在九四，兩剛相遇，其情不相得。此意亦可備一解。</p><h2 id="初九佔" tabindex="-1">初九佔 <a class="header-anchor" href="#初九佔" aria-label="Permalink to “初九佔”">​</a></h2><p>○　問時運：目下尚未交盛運，須刻苦自勉，待好運到來，自然得利。</p><p>○　問商業：想是基業初創，百貨未曾交辦，須要謹守其初，自得無害而有利也。</p><p>○　問戰徵：必是初次動眾，尚未交鋒，須要慎始，自無後患。</p><p>○　問家宅：必是新富之家，艱難創業，自得後福。</p><p>○　問訟事：尚未投告，還宜和息為善。</p><p>○　問行人：尚未有歸志也。</p><p>○　問六甲：生男，產期尚遠。</p><p>○　問失物：一時難以即得，待久可有。</p><h2 id="初九案例" tabindex="-1">初九案例 <a class="header-anchor" href="#初九案例" aria-label="Permalink to “初九案例”">​</a></h2><p>佐賀縣士族深江某，餘之親友也。明治四年，從事紙石灰等商業，來橫濱為奸商所敗。此人雖有才學，不慣商業，請餘佔後來氣運，策得《大有》之《鼎》。</p><p>斷曰：此卦《大有》，足見後運昌盛。今九居初爻，是將近運來之時，故不免為小人所害。雖近來有意外之損失，原來足下於商業本未慣習，雖有小害，未足咎也。今謀出仕官途，將來必得升遷，但一值盛運，不思厥艱，咎必難免。惟持盈保泰，雖有而不忘其艱，時時刻苦自勉，以今日之苦，期他日之亨，即得他日之亨，又仍慮今日之苦，不忘其艱，則無咎也。如是，則可長保其有矣。願足下勉之！後果如此佔。</p><p>相識某縣人永井某來，請佔氣運，筮得《大有》之《鼎》。</p><p>斷曰：卦曰《大有》，已兆資產豐足之象，可欣可喜。今得初爻，知為一時之初運，未得大利，若不思經營之難，稍涉驕盈，便幹災害，萬宜戒慎。就尊府論之，尊大人性情篤實，平生桔據勉勵，未能擴充家計。足下意猶未滿，欲發一攫千金之念，幸此盛運初交，得此利益，是正《大有》之初爻也。其辭曰：“初九，無交害，非咎，艱則無咎。”此艱字，最宜審慎。蓋謂爻居初九，未與物交，是以“非咎”，一經交際，害即伏之，若不思克艱，咎必難免矣。慎之勉之！某氏一時雖面從我言，然年少意氣，不能自抑，漸耽驕奢，卒致敗事，遂即非行，而陷囹圄。爻象垂誡，不爽如此，豈不可畏哉！</p><h2 id="九二解" tabindex="-1">九二解 <a class="header-anchor" href="#九二解" aria-label="Permalink to “九二解”">​</a></h2><p>此爻以陽居二，陰陽剛柔，適得其宜。當大有之時，居臣下之位，上應六五之君，是具大有為之才，遇大有為之時，以一身而任國家之重者也。二陰柔，是以能容，九陽剛，是以能行，象車。初、三兩剛，比輔於左右，為“大車”，故曰“大車以載”，謂其才之足以任重而行遠也。二以剛中之德，恢有容之量，能以天下之人才，屬之於群，量才器使，俾得各效厥職，而無有叢脞，故曰“有攸往，無咎”。佔者如此，則位足以酬其志，德足以堪其任，上不負君之所託，下不失民之所望，何咎之有？《象傳》曰“積中不敗也”者，言大車得初三左右兩剛比輔，車體完厚，雖積重於中，行遠而不敗，猶九二才力剛強，能肩當天下之重，斷無敗事之虞也。此爻變則為《離》，《離》六二辭曰，“黃離，元吉”，可以參考也。</p><h2 id="九二佔" tabindex="-1">九二佔 <a class="header-anchor" href="#九二佔" aria-label="Permalink to “九二佔”">​</a></h2><p>○　問時運：目下正交好運，一路順風，無往不利。</p><p>○　問商業：販運貨物，貿遷有無，極之域外通商，無不獲利。</p><p>○　問戰徵：利於陸戰，率軍直進，攻取皆捷。</p><p>○　問家宅：平安無咎，若謀高遷，更吉。</p><p>○　問疾病：宜出外就醫，吉。</p><p>○　問行人：因在外謀事，諸多利益，一時未歸。</p><p>○　問訟事：得勝。</p><p>○　問六甲：生男，逾月則生女。</p><h2 id="九二案例" tabindex="-1">九二案例 <a class="header-anchor" href="#九二案例" aria-label="Permalink to “九二案例”">​</a></h2><p>明治二年，友人來請佔某貴顯氣運，筮得《大有》之《離》。</p><p>斷曰：此卦六五一陰居君位，統御五陽。內卦為《乾》．《乾》綱獨攬，正大之象；外卦為《離》，《離》明普照，光明之象。光明正大而有天下，謂之《大有》。二爻具剛中之德，與六五之君，陰陽相應，能積載天下之大任，輔佐天下之大業，恰如大車運轉自在，謂之大“車以載，有攸往，無咎”。據此爻辭，知某貴顯，後必當大任，奏大功也。後果如此佔。</p><p>佔明治三十二年，佔德國之氣運，筮得《大有》之《離》。</p><p>斷曰：此卦五爻陰得中，統御五剛，恰如德帝統御普國，眾民悅服，國中兵食完備，戰守咸宜，正國軍盛大之象。今得二爻，其辭曰“大車以載，有攸往，無咎，”可以見矣。</p><h2 id="九三解" tabindex="-1">九三解 <a class="header-anchor" href="#九三解" aria-label="Permalink to “九三解”">​</a></h2><p>“亨”與享同。“公用亨於天子”者，謂天子設筵，宴會公侯也。九三與之，此爻居下卦之上，公侯之象。九五之君，虛己下賢，一時四方公侯，感化來賓，如《詩》所詠“喜賓安樂，寥獲湛露”之義是也，故曰“公用享於天子”。蓋諸侯之於天子，藩屏王家，天子喜其功，宴享而勞之。此爻以陽居陽，具純正之才德，可得與此寵榮，若使小人當此，捧富有，擅威福，慢上凌下，必招禍患，安得與享禮之優待乎？上無比應，君上必不信任，故曰“小人弗克”，《象傳》亦曰“小人害也”。一說“享於天子”者，謂能以所有貢奉於君上。凡土地之富，人民之眾，皆天子之有也，諸侯謹守臣節，忠順奉上，撫育黎庶，以效屏藩，豐殖貨財。以資貢獻，享之天於，以其有為天子之有也。若小人而居此位，則私有其富，不復知奉公之道，故曰“小人弗克”。此義亦通。按：凡《易》辭曰“先王者，以垂統言；曰“帝”者，以主宰言；曰“天子”者，以正位言；又“後”者，天子諸侯之通稱；“大君”者，天子之尊稱也。</p><h2 id="九三佔" tabindex="-1">九三佔 <a class="header-anchor" href="#九三佔" aria-label="Permalink to “九三佔”">​</a></h2><p>○　問時運：目下正當顯榮之時，利為公，不利營私。</p><p>○　問仕途：恰得寵任榮賞之象，若取賂必敗，宜慎。</p><p>○　問商業：不特得利，且可得名。</p><p>○　問戰徵：有犒賞三軍之象，得獲勝仗，恐於兵眾有《損》。</p><p>○　問家宅：有喜慶宴會之象，家食豐富，但使用婢僕中，須當留意。</p><p>○　問訟事：若為飲食起釁，恐難得直。</p><p>○　問六甲：生男。主貴，但幼小時，防多疾厄。</p><h2 id="九三案例" tabindex="-1">九三案例 <a class="header-anchor" href="#九三案例" aria-label="Permalink to “九三案例”">​</a></h2><p>大阪友人某來，請佔某豪商時運，筮得《大有》之《睽》。</p><p>斷曰：此卦《大有》，可知為富豪之家。“公用享於天子”者，為大臣寵荷君恩也。在商人處涉王事，得官家優待，其象亦同。商人而獲此寵遇，宜慎守其常，切勿恃勢怙寵，不然，挾富有，假威權，恃寵而驕，必損資產。吉凶悔吝，惟在其人自取而己。其後某豪富，管理某省用途金，與貴顯交往，自負富有，頗招人怨，偶罹病死，不能辦償官金，致破其產。</p><p>明治五年，土州人渡邊小一郎來，請佔氣運，筮得《大有》之《睽》。</p><p>斷曰：《大有》之世，天子虛己用賢，金帛之出納委之臣下，大臣為能謹慎任事，小人則必失奉上之道，故辭曰“公用享於天子，小人弗克。”足下令負擔鐵道局神戶出張所事務，出納金錢，最宜注意。昔封建之世，士民共有義氣，往往有監守自盜者，則屠腹而謝其罪。維新以來，刑法寬緩，人少廉恥，不可不深留意也。後在神戶，某屬員為私買米市，偷用官金若干，渡邊氏亦不免其責，且為救護屬員，借入某商人之金若干，以辦償官金。後事發覺，與屬員某共處其罪雲。</p><p>江京虎之門，琴平神社宮司鴻雪爪者，餘之知己也。二十九年某月，來告曰：頃日淺野侯爵罹大患，以其危篤，不堪憂慮，請筮一卦，以佔休咎。筮得《大有》之《睽》。</p><p>斷曰：《大有》者，以示生命之有在也。上爻為有之終，恰值歸魂，今佔得三艾，病之用享，利在藥餌，知必昨良醫奏功也。”貧賤輩請良醫難得，良藥萬難。“克”者，愈也，故在小人或防“弗克”，在侯之家，良醫易招，即貴重藥品，亦易購覓，故謂之“王用享於天子”。如得天子之賞賜良藥也，病必無礙。後果快愈，今猶無恙也。</p><h2 id="九四解" tabindex="-1">九四解 <a class="header-anchor" href="#九四解" aria-label="Permalink to “九四解”">​</a></h2><p>“彭”者，盛多貌。《詩》曰“行人彰彭”，曰“出車彭彭”，曰“駟彭彭”曰“四牡彭彭”皆形容人馬之強盛也。此爻以剛居柔，當《大有》之時，在執政之位，有剛明之才德，立眾賢之上，與六五之君，陰陽親比，君上之眷顧至渥，寵遇殊盛，所謂位極人臣，威權富貴，萃於一身，是處過盛之勢者也。過盛則可危，惟能體《離》之明，居柔善遜，見幾而避，雖處其盛，以為非已之盛也，故曰“非其彭，無咎”。《象傳》釋“無咎”曰，“明辨析也”，“析”者明之體，“明辨”者，得外卦《離》日之象。一說以“匪”為篚，此爻威權之盛，天下之人，輻輳其門，非無贈賄之嫌。身居大臣之地，運值《大有》之時，瑣瑣贈賄，何足動其心乎？是謂“非其彭，無咎”。《易》之取象廣大，不容偏執一義也。</p><h2 id="九四佔" tabindex="-1">九四佔 <a class="header-anchor" href="#九四佔" aria-label="Permalink to “九四佔”">​</a></h2><p>○　問時運：六爻已值其四，是目下已到極盛之會，當持盈保泰，知止不辱。</p><p>○　問商業：已得利益，毋過貪求，斯無害。</p><p>○　問家宅：必苟完苟美，如衛公子荊之居室，則善矣，否則未免盈滿有損。</p><p>○　問疾病：防有膨脹之患。</p><p>○　問六甲：生男。</p><p>○　問訟事：得明決之才，判斷得直。</p><p>○　問失物：在竹篚內尋之。</p><h2 id="九四案例" tabindex="-1">九四案例 <a class="header-anchor" href="#九四案例" aria-label="Permalink to “九四案例”">​</a></h2><p>親友某氏，以商業旅行，託餘代襄其事。一夜深更，其夥友某，突來哀訴曰：有一疑事，而不知所措，請一佔為解。僕窮厄，今朝有一商來，領受金三百元，藏之簟笥，忘施鎖鑰，至夕檢取，不見其金。或疑遺忘他所，搜索不得，於是檢查朝來出入，及在家者，其人皆夙所信任，無可疑者，遺失所由，實不可知。筮得《大有》之《家人》。</p><p>斷曰：卦名曰《大有》，知未出外，而在家中可知也。又以卦擬全家，上卦者為二階，爻辭曰“匪其彭，無咎”，“匪”者，盛玉帛之竹器，子宜速還，檢二階之竹器，必可得之也。某謝而去，少頃來報曰，果發見之於二階之竹器中也。</p><h2 id="六五解" tabindex="-1">六五解 <a class="header-anchor" href="#六五解" aria-label="Permalink to “六五解”">​</a></h2><p>“孚”者，所以通上下之情；“威”者，所以嚴上下之分也。情不通則高，分不嚴則褻。“交如”者，交接之義；“威如”者，威嚴之義。孔子曰，“正其衣冠，尊其瞻視，儼然人望而畏之”，此之謂也。此爻以柔中居尊位，虛心禮賢，下應九二，上下五陽，皆歸其德，故曰“厥孚”。明良一德，朝野傾心，如良友之善交，故曰“交如”。然君心貴和，而君體貴尊，所謂有儀可象，有威可畏，故曰“威如”。蓋《大有》之世，在下者有協助之志，在上者又能誠信接下，足以感發之，故《象傳》曰“信以發志也”。又《象傳》曰“易而無備也”者，六五居群剛之間，獨用柔道，未免為人所易慢，而無畏怖之心也。</p><h2 id="六五佔" tabindex="-1">六五佔 <a class="header-anchor" href="#六五佔" aria-label="Permalink to “六五佔”">​</a></h2><p>○　問時運：必其平生為人所信服，且有威望，晚運亨佳之會也。</p><p>○　問商業：一時眾商信服，貨物通行，可永保其富有也。</p><p>○　問戰徵：眾軍勇躍，威令遠揚，尤宜警備，以防敵軍。</p><p>○　問家宅：主一家和睦，恐有盜竊，宜備防也。</p><p>○　問失物：所竊者即信用之人，以威逼之，必交還也。但恐得而復失。</p><p>○　問六甲：生男。</p><p>○　問訟事：被告者必畏威而和。</p><p>○　問行人：如期而歸。</p><h2 id="六五案例" tabindex="-1">六五案例 <a class="header-anchor" href="#六五案例" aria-label="Permalink to “六五案例”">​</a></h2><p>一日親友某來，請佔氣運，筮得《大有》之《乾》。</p><p>斷曰：此卦擬之於國家，六五柔中之君，備公明、正大、威信、溫和之德，與九二陰陽相應，與九四陰陽相比，統御眾陽，以保大有之治，以一個人觀之亦同。足下信用忠實之夥友，虛己而容人，以眾之喜為己之喜，以眾之憂為已之憂，主僕相和，家政克行。然有不可無威，無威則命令不行，國政然，家政亦然。今當大有之時，預體此意，可注意於恩威並行也。某氏守之，家業益臻繁昌。</p><h2 id="上九解" tabindex="-1">上九解 <a class="header-anchor" href="#上九解" aria-label="Permalink to “上九解”">​</a></h2><p>此爻居《大有》之極，不居其有者也。以剛在六五國君之後，可謂盡人事而待天命者也，是賢師付也。為能則天道，以計劃國政，使《大有》之君，應天時，統萬機，積德行，享有全盛之福。此非“自天佑之”，豈能享其有哉！所謂不期而自致者。當此時得天助之，凡百事業，無不吉利，故曰“自天佑之，吉無不利”。夫聖人之作《易》其要在天助人歸，如雲“天之所助者順也，人之所助者信也”。此爻之辭，可謂一言足以蔽三百八十四爻也。</p><h2 id="上九佔" tabindex="-1">上九佔 <a class="header-anchor" href="#上九佔" aria-label="Permalink to “上九佔”">​</a></h2><p>○　問時運：目下一路好運，萬事皆吉。</p><p>○　問商業：百貨皆獲利。</p><p>○　問家宅：一門福慶。</p><p>○　問戰徵：即此一戰，軍功大捷，可罷師也。</p><p>○　問行人：即歸。</p><p>○　問疾病：默得神佑，吉。</p><p>○　問六甲：生男。</p><p>○　問失物：就高處尋覓，可得。</p><h2 id="上九案例" tabindex="-1">上九案例 <a class="header-anchor" href="#上九案例" aria-label="Permalink to “上九案例”">​</a></h2><p>明治十五年，佔某貴顯氣運，筮得《大有》之《大壯》。</p><p>斷曰：此卦如日之輝天，五陽之眾賢輔翼之，得見《大有》之治。今佔得此爻，積善積德，得自天佑，天下之事業，無不吉利，謂之“自天佑之，吉無不利”。然此年某貴顯死去，以卦《大有》之終為歸魂，即謂之歸天也。</p>',109)])])}const m=p(i,[["render",l]]);export{b as __pageData,m as default};
